}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: set MinSum to 50
        c.SetMinSum(50);
        c.Initialized();

        // Alice deposits 50 wei, Bob deposits 100 wei
        vm.deal(address(0x1111), 50);
        vm.prank(address(0x1111));
        c.Deposit{value: 50}();

        vm.deal(address(0x2222), 100);
        vm.prank(address(0x2222));
        c.Deposit{value: 100}();

        // Bob calls Collect(50)
        vm.prank(address(0x2222));
        c.Collect(50);

        // Assertion: after Collect, Bob's balance should be 50 (reference) not 150 (bug)
        assertTrue(c.balances(address(0x2222)) == 50);
    }
}
